addEventListener('fetch', event => {
  event.respondWith(handleRequest(event.request))
})

const HTML = "<!DOCTYPE html>\n<html lang=\"so\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Serabta</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;1,400&family=Inter:wght@300;400;500&display=swap\" rel=\"stylesheet\">\n<style>\n*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}\n:root{--noir:#04040c;--ivoire:#f0ece4;--rouge:#8b1a1a;--or:#c9a84c;--bleu:#0a0a2e}\n\nhtml,body{width:100%;height:100%;overflow:hidden;background:var(--noir)}\nbody{color:var(--ivoire);font-family:'Inter',sans-serif;display:flex;align-items:center;justify-content:center;perspective:1400px}\n\n/* \u2550\u2550\u2550 CANVAS \u2550\u2550\u2550 */\n#canvas{position:fixed;inset:0;z-index:0;pointer-events:none}\n\n/* \u2550\u2550\u2550 BLOBS ULTRA \u2550\u2550\u2550 */\n.blob{position:fixed;border-radius:50%;filter:blur(90px);pointer-events:none;z-index:0;mix-blend-mode:screen}\n.b1{width:600px;height:600px;background:radial-gradient(circle,#8b1a1a,transparent);opacity:.35;top:-200px;left:-200px;animation:B1 12s ease-in-out infinite alternate}\n.b2{width:500px;height:500px;background:radial-gradient(circle,#c9a84c,transparent);opacity:.3;bottom:-150px;right:-150px;animation:B2 15s ease-in-out infinite alternate}\n.b3{width:350px;height:350px;background:radial-gradient(circle,#1a0a4e,transparent);opacity:.5;top:35%;left:30%;animation:B3 9s ease-in-out infinite alternate}\n.b4{width:200px;height:200px;background:radial-gradient(circle,#4e1a1a,transparent);opacity:.4;top:10%;right:10%;animation:B4 7s ease-in-out infinite alternate}\n@keyframes B1{from{transform:translate(0,0) scale(1) rotate(0deg)}to{transform:translate(80px,60px) scale(1.2) rotate(15deg)}}\n@keyframes B2{from{transform:translate(0,0) scale(1)}to{transform:translate(-60px,-40px) scale(1.15)}}\n@keyframes B3{from{transform:translate(0,0) scale(1) rotate(0deg)}to{transform:translate(40px,30px) scale(1.3) rotate(-20deg)}}\n@keyframes B4{from{transform:translate(0,0) scale(1)}to{transform:translate(-20px,30px) scale(1.4)}}\n\n/* \u2550\u2550\u2550 WRAPPER \u2550\u2550\u2550 */\n.wrapper{position:relative;z-index:10;width:100%;max-width:420px;padding:1.2rem;height:100vh;display:flex;align-items:center;justify-content:center;transform-style:preserve-3d}\n\n/* \u2550\u2550\u2550 CARD \u2550\u2550\u2550 */\n.card{\n  width:100%;\n  background:rgba(4,4,16,0.55);\n  backdrop-filter:blur(40px);-webkit-backdrop-filter:blur(40px);\n  border:1px solid rgba(255,255,255,0.08);\n  border-radius:32px;\n  padding:2.5rem 1.8rem;\n  position:relative;overflow:hidden;\n  transform-style:preserve-3d;\n  box-shadow:0 30px 100px rgba(0,0,0,0.8),0 0 80px rgba(139,26,26,0.15),0 0 50px rgba(201,168,76,0.08),inset 0 1px 0 rgba(255,255,255,0.1);\n  animation:cardEntrance 1.2s cubic-bezier(0.16,1,0.3,1) forwards;\n  opacity:0;\n}\n@keyframes cardEntrance{\n  0%{opacity:0;transform:translateY(100px) rotateX(25deg) scale(0.8)}\n  60%{opacity:1}\n  100%{opacity:1;transform:translateY(0) rotateX(0deg) scale(1)}\n}\n.card::before{content:'';position:absolute;top:-1px;left:10%;right:10%;height:1px;background:linear-gradient(to right,transparent,rgba(201,168,76,.8),rgba(255,255,255,.5),rgba(201,168,76,.8),transparent);animation:toplineGlow 3s ease-in-out infinite alternate}\n@keyframes toplineGlow{from{opacity:.5;left:20%;right:20%}to{opacity:1;left:5%;right:5%}}\n.card::after{content:'';position:absolute;bottom:-1px;left:20%;right:20%;height:1px;background:linear-gradient(to right,transparent,rgba(139,26,26,.6),transparent)}\n.card-shine{position:absolute;inset:0;border-radius:32px;background:radial-gradient(circle at 50% 0%,rgba(255,255,255,.06) 0%,transparent 60%);pointer-events:none;z-index:0;transition:background .1s}\n\n/* \u2550\u2550\u2550 PAGES \u2550\u2550\u2550 */\n.page{width:100%;display:none;flex-direction:column;align-items:center;opacity:0;transform:translateX(60px) scale(.96) rotateY(12deg);pointer-events:none;transition:opacity .5s cubic-bezier(.16,1,.3,1),transform .5s cubic-bezier(.16,1,.3,1);transform-style:preserve-3d}\n.page.active{display:flex;opacity:1;transform:translateX(0) scale(1) rotateY(0deg);pointer-events:all}\n.page.exit{display:flex;opacity:0;transform:translateX(-60px) scale(.96) rotateY(-12deg);pointer-events:none}\n\n/* \u2550\u2550\u2550 PHOTO 3D \u2550\u2550\u2550 */\n.photo-outer{position:relative;width:150px;height:150px;margin-bottom:1.6rem;opacity:0;transform:translateY(-50px) scale(.6) rotateY(30deg)}\n.photo-outer.in{opacity:1;transform:translateY(0) scale(1) rotateY(0deg);transition:opacity .9s cubic-bezier(.16,1,.3,1) .4s,transform .9s cubic-bezier(.16,1,.3,1) .4s;animation:photoFloat 5s 1.4s ease-in-out infinite}\n@keyframes photoFloat{\n  0%,100%{transform:translateY(0) rotateX(0deg) rotateY(0deg)}\n  25%{transform:translateY(-10px) rotateX(6deg) rotateY(6deg)}\n  50%{transform:translateY(-5px) rotateX(0deg) rotateY(12deg)}\n  75%{transform:translateY(-12px) rotateX(-6deg) rotateY(4deg)}\n}\n/* Triple ring */\n.ring1,.ring2,.ring3{position:absolute;border-radius:50%}\n.ring1{inset:-6px;background:conic-gradient(var(--or) 0%,var(--rouge) 30%,#fff 50%,var(--rouge) 70%,var(--or) 100%);animation:spin 2.5s linear infinite;filter:drop-shadow(0 0 15px rgba(201,168,76,.8))}\n.ring2{inset:-14px;background:conic-gradient(rgba(139,26,26,.6),transparent 40%,rgba(201,168,76,.4),transparent 80%,rgba(139,26,26,.6));animation:spin 4s linear infinite reverse;filter:blur(3px);opacity:.7}\n.ring3{inset:-22px;background:conic-gradient(rgba(201,168,76,.2),transparent 50%,rgba(201,168,76,.2));animation:spin 8s linear infinite;filter:blur(6px);opacity:.5}\n@keyframes spin{to{transform:rotate(360deg)}}\n/* Rays */\n.rays{position:absolute;inset:-30px;border-radius:50%;background:conic-gradient(rgba(201,168,76,.3) 0deg,transparent 25deg,rgba(139,26,26,.2) 50deg,transparent 75deg,rgba(201,168,76,.3) 100deg,transparent 125deg,rgba(139,26,26,.2) 150deg,transparent 175deg,rgba(201,168,76,.3) 200deg,transparent 225deg,rgba(139,26,26,.2) 250deg,transparent 275deg,rgba(201,168,76,.3) 300deg,transparent 325deg,rgba(139,26,26,.2) 350deg,transparent 360deg);animation:spin 10s linear infinite;filter:blur(8px);opacity:.8}\n.photo-inner{position:relative;z-index:1;width:100%;height:100%;border-radius:50%;overflow:hidden;border:4px solid var(--noir);box-shadow:0 15px 50px rgba(0,0,0,.7),0 0 30px rgba(201,168,76,.4)}\n.photo-inner img{width:100%;height:100%;object-fit:cover;object-position:top center}\n.photo-shadow{position:absolute;bottom:-18px;left:50%;transform:translateX(-50%);width:90px;height:14px;background:radial-gradient(ellipse,rgba(201,168,76,.5) 0%,transparent 70%);border-radius:50%;animation:shadowPulse 5s ease-in-out infinite}\n@keyframes shadowPulse{0%,100%{transform:translateX(-50%) scale(1);opacity:.5}50%{transform:translateX(-50%) scale(.6);opacity:.2}}\n\n/* \u2550\u2550\u2550 TEXT \u2550\u2550\u2550 */\n.name{font-family:'Playfair Display',serif;font-size:2.3rem;font-weight:700;text-align:center;background:linear-gradient(135deg,#fff 0%,var(--or) 45%,var(--rouge) 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:.4rem;opacity:0;transform:translateY(25px) scale(.85);animation:nameGlow 3s ease-in-out infinite alternate}\n.name.in{opacity:1;transform:translateY(0) scale(1);transition:opacity .7s cubic-bezier(.16,1,.3,1) .65s,transform .7s cubic-bezier(.16,1,.3,1) .65s}\n@keyframes nameGlow{from{filter:drop-shadow(0 0 8px rgba(201,168,76,.3))}to{filter:drop-shadow(0 0 30px rgba(201,168,76,.9))}}\n\n.role{font-size:.68rem;letter-spacing:.32em;text-transform:uppercase;color:rgba(240,236,228,.4);margin-bottom:1.6rem;text-align:center;opacity:0;transform:translateY(15px)}\n.role.in{opacity:1;transform:translateY(0);transition:opacity .6s ease .85s,transform .6s ease .85s}\n\n.divider{width:0;height:1px;background:linear-gradient(to right,transparent,var(--or),var(--rouge),var(--or),transparent);margin-bottom:1.6rem;opacity:0;animation:divPulse 2s ease-in-out infinite alternate}\n.divider.in{opacity:1;width:70px;transition:width .8s cubic-bezier(.16,1,.3,1) 1s,opacity .4s ease 1s}\n@keyframes divPulse{from{width:50px;opacity:.6}to{width:80px;opacity:1}}\n\n/* \u2550\u2550\u2550 BUTTONS \u2550\u2550\u2550 */\n.links{display:flex;flex-direction:column;gap:.9rem;width:100%}\n.link-btn{display:flex;align-items:center;justify-content:center;gap:.75rem;padding:1rem 1.5rem;border-radius:16px;color:var(--ivoire);font-size:.83rem;letter-spacing:.12em;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);cursor:pointer;font-family:'Inter',sans-serif;position:relative;overflow:hidden;transition:transform .3s cubic-bezier(.34,1.56,.64,1),box-shadow .3s,border-color .3s;transform-style:preserve-3d;opacity:0;transform:translateY(30px) scale(.85)}\n.link-btn.in{opacity:1;transform:translateY(0) scale(1)}\n.link-btn:nth-child(1).in{transition:opacity .6s cubic-bezier(.34,1.56,.64,1) 1.1s,transform .6s cubic-bezier(.34,1.56,.64,1) 1.1s}\n.link-btn:nth-child(2).in{transition:opacity .6s cubic-bezier(.34,1.56,.64,1) 1.25s,transform .6s cubic-bezier(.34,1.56,.64,1) 1.25s}\n.link-btn::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(201,168,76,.2),rgba(139,26,26,.15));opacity:0;transition:opacity .3s;border-radius:16px}\n.link-btn::after{content:'';position:absolute;top:0;left:-100%;width:60%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.08),transparent);transition:left .5s ease;transform:skewX(-15deg)}\n.link-btn:hover{transform:translateY(-5px) scale(1.03) rotateX(4deg);border-color:rgba(201,168,76,.5);box-shadow:0 20px 50px rgba(0,0,0,.5),0 0 25px rgba(201,168,76,.2)}\n.link-btn:hover::before{opacity:1}\n.link-btn:hover::after{left:150%}\n.link-btn:active{transform:translateY(-1px) scale(.99)}\n.link-btn svg{width:18px;height:18px;flex-shrink:0;position:relative;z-index:1}\n.link-btn span{position:relative;z-index:1}\n\n/* \u2550\u2550\u2550 FORM \u2550\u2550\u2550 */\n.form-page{align-items:flex-start}\n.page-title{font-family:'Playfair Display',serif;font-size:1.7rem;font-weight:700;margin-bottom:.3rem;background:linear-gradient(135deg,var(--ivoire),var(--or));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;filter:drop-shadow(0 0 12px rgba(201,168,76,.4))}\n.subtitle{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(240,236,228,.35);margin-bottom:1.4rem}\n.field{margin-bottom:.9rem;width:100%}\nlabel{display:block;font-size:.67rem;letter-spacing:.2em;text-transform:uppercase;color:rgba(240,236,228,.4);margin-bottom:.4rem}\ninput,textarea,select{width:100%;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:.8rem 1rem;color:var(--ivoire);font-family:'Inter',sans-serif;font-size:.88rem;outline:none;transition:border-color .3s,box-shadow .3s,transform .2s}\ninput:focus,textarea:focus,select:focus{border-color:rgba(201,168,76,.6);box-shadow:0 0 0 3px rgba(201,168,76,.1),0 0 20px rgba(201,168,76,.1);transform:translateY(-2px)}\nselect option{background:#0a0a18}\ntextarea{resize:none;height:80px}\n.btn-send{width:100%;padding:1rem;background:linear-gradient(135deg,var(--or),#a07830,var(--rouge));background-size:300% 300%;color:#fff;border:none;border-radius:14px;font-family:'Inter',sans-serif;font-size:.78rem;font-weight:600;letter-spacing:.2em;text-transform:uppercase;cursor:pointer;margin-top:1rem;display:flex;align-items:center;justify-content:center;gap:.6rem;opacity:.3;pointer-events:none;transition:opacity .3s,transform .3s cubic-bezier(.34,1.56,.64,1),box-shadow .3s}\n.btn-send.active{opacity:1;pointer-events:all;animation:gradShift 3s ease infinite;box-shadow:0 8px 30px rgba(201,168,76,.4),0 0 20px rgba(139,26,26,.3)}\n@keyframes gradShift{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}\n.btn-send.active:hover{transform:translateY(-3px) scale(1.02);box-shadow:0 15px 40px rgba(201,168,76,.5),0 0 30px rgba(139,26,26,.4)}\n.back-btn{margin-top:1rem;font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(240,236,228,.3);background:none;border:none;cursor:pointer;font-family:'Inter',sans-serif;transition:color .3s,transform .2s;align-self:flex-start}\n.back-btn:hover{color:var(--ivoire);transform:translateX(-4px)}\n\n/* \u2550\u2550\u2550 INTRO SCREEN \u2550\u2550\u2550 */\n#intro{position:fixed;inset:0;z-index:99999;background:#020208;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;transition:opacity 1.2s ease,visibility 1.2s ease}\n#intro.hide{opacity:0;visibility:hidden;pointer-events:none}\n#intro-canvas{position:absolute;inset:0;z-index:0}\n.intro-scene{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;animation:sceneFloat 6s ease-in-out infinite}\n@keyframes sceneFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}\n\n.intro-ring-wrap{position:relative;width:210px;height:210px;margin-bottom:1.8rem;transform-style:preserve-3d;animation:introTilt 5s ease-in-out infinite}\n@keyframes introTilt{0%,100%{transform:rotateX(8deg) rotateY(0deg)}33%{transform:rotateX(-4deg) rotateY(18deg)}66%{transform:rotateX(10deg) rotateY(-12deg)}}\n\n.i-ring1{position:absolute;inset:-8px;border-radius:50%;background:conic-gradient(var(--or) 0%,var(--rouge) 25%,#fff 45%,var(--or) 60%,var(--rouge) 80%,var(--or) 100%);animation:spin 2s linear infinite;filter:drop-shadow(0 0 20px rgba(201,168,76,.9))}\n.i-ring2{position:absolute;inset:-18px;border-radius:50%;background:conic-gradient(rgba(139,26,26,.7),transparent 35%,rgba(201,168,76,.5),transparent 75%,rgba(139,26,26,.7));animation:spin 3.5s linear infinite reverse;filter:blur(4px);opacity:.8}\n.i-ring3{position:absolute;inset:-30px;border-radius:50%;background:conic-gradient(rgba(201,168,76,.3),transparent 50%,rgba(201,168,76,.3));animation:spin 7s linear infinite;filter:blur(8px);opacity:.6}\n.i-rays{position:absolute;inset:-50px;border-radius:50%;background:conic-gradient(rgba(201,168,76,.25) 0deg,transparent 20deg,rgba(139,26,26,.15) 40deg,transparent 60deg,rgba(201,168,76,.25) 80deg,transparent 100deg,rgba(139,26,26,.15) 120deg,transparent 140deg,rgba(201,168,76,.25) 160deg,transparent 180deg,rgba(139,26,26,.15) 200deg,transparent 220deg,rgba(201,168,76,.25) 240deg,transparent 260deg,rgba(139,26,26,.15) 280deg,transparent 300deg,rgba(201,168,76,.25) 320deg,transparent 340deg,rgba(139,26,26,.15) 360deg);animation:spin 12s linear infinite;filter:blur(10px)}\n.i-photo{position:relative;z-index:1;width:210px;height:210px;border-radius:50%;overflow:hidden;border:4px solid #020208;box-shadow:0 0 80px rgba(201,168,76,.6),0 0 150px rgba(139,26,26,.5)}\n.i-photo img{width:100%;height:100%;object-fit:cover;object-position:top center}\n\n.intro-name-wrap{overflow:hidden;margin-bottom:.4rem;opacity:0;transform:translateY(50px) scale(.8);transition:opacity .9s cubic-bezier(.16,1,.3,1) .3s,transform .9s cubic-bezier(.16,1,.3,1) .3s}\n.intro-name-wrap.show{opacity:1;transform:translateY(0) scale(1)}\n.intro-name{font-family:'Playfair Display',serif;font-size:clamp(2.5rem,10vw,4.5rem);font-weight:700;letter-spacing:.08em;background:linear-gradient(135deg,#fff 0%,var(--or) 40%,var(--rouge) 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;animation:iNameGlow 2s ease-in-out infinite alternate}\n@keyframes iNameGlow{from{filter:drop-shadow(0 0 10px rgba(201,168,76,.4))}to{filter:drop-shadow(0 0 50px rgba(201,168,76,1))}}\n\n.intro-role{font-size:.68rem;letter-spacing:.35em;text-transform:uppercase;color:rgba(240,236,228,.5);margin-bottom:1.8rem;opacity:0;transform:translateY(20px);transition:opacity .7s ease .6s,transform .7s ease .6s}\n.intro-role.show{opacity:1;transform:translateY(0)}\n\n.intro-bars{display:flex;gap:5px;align-items:flex-end;height:45px;margin-bottom:1.8rem;opacity:0;transition:opacity .4s ease}\n.intro-bars.show{opacity:1}\n.intro-bars span{width:5px;border-radius:3px;background:linear-gradient(to top,var(--rouge),var(--or));animation:barBeat .6s ease-in-out infinite alternate}\n.intro-bars span:nth-child(1){height:12px;animation-delay:0s}\n.intro-bars span:nth-child(2){height:28px;animation-delay:.1s}\n.intro-bars span:nth-child(3){height:40px;animation-delay:.05s}\n.intro-bars span:nth-child(4){height:22px;animation-delay:.15s}\n.intro-bars span:nth-child(5){height:35px;animation-delay:.08s}\n.intro-bars span:nth-child(6){height:18px;animation-delay:.12s}\n.intro-bars span:nth-child(7){height:30px;animation-delay:.03s}\n.intro-bars span:nth-child(8){height:14px;animation-delay:.18s}\n@keyframes barBeat{from{transform:scaleY(.2);opacity:.4}to{transform:scaleY(1);opacity:1}}\n\n.intro-btn{padding:1.1rem 3.5rem;background:linear-gradient(135deg,var(--or),var(--rouge));background-size:200% 200%;color:#fff;border:none;border-radius:50px;font-family:'Inter',sans-serif;font-size:.82rem;font-weight:600;letter-spacing:.25em;text-transform:uppercase;cursor:pointer;opacity:0;transform:translateY(25px) scale(.9);transition:opacity .7s ease,transform .7s cubic-bezier(.34,1.56,.64,1);box-shadow:0 10px 40px rgba(201,168,76,.5),0 0 80px rgba(139,26,26,.4);position:relative;overflow:hidden}\n.intro-btn::before{content:'';position:absolute;top:0;left:-100%;width:60%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.2),transparent);animation:btnShine 2.5s ease infinite;transform:skewX(-20deg)}\n@keyframes btnShine{0%{left:-100%}100%{left:200%}}\n.intro-btn.show{opacity:1;transform:translateY(0) scale(1)}\n.intro-btn:hover{transform:scale(1.06) translateY(-3px);box-shadow:0 20px 60px rgba(201,168,76,.7),0 0 100px rgba(139,26,26,.6)}\n.intro-btn:active{transform:scale(.98)}\n\n/* Mobile */\n@media(max-width:600px){\n  html,body{overflow-y:auto;height:auto;background:#04040c!important}\n  .wrapper{height:auto;min-height:100vh;padding:1rem}\n  .card{padding:2rem 1.4rem;border-radius:24px}\n  .b1,.b2{opacity:.45}\n}\n@supports(-webkit-touch-callout:none){\n  .wrapper{min-height:-webkit-fill-available}\n}\n</style>\n</head>\n<body>\n\n<!-- CANVAS BG -->\n<canvas id=\"canvas\"></canvas>\n<div class=\"blob b1\"></div>\n<div class=\"blob b2\"></div>\n<div class=\"blob b3\"></div>\n<div class=\"blob b4\"></div>\n\n<!-- \u2550\u2550\u2550 INTRO \u2550\u2550\u2550 -->\n<div id=\"intro\">\n  <canvas id=\"intro-canvas\"></canvas>\n  <div class=\"intro-scene\">\n    <div class=\"intro-ring-wrap\">\n      <div class=\"i-rays\"></div>\n      <div class=\"i-ring3\"></div>\n      <div class=\"i-ring2\"></div>\n      <div class=\"i-ring1\"></div>\n      <div class=\"i-photo\"><img src=\"data:image/png;base64,\" alt=\"Serabta\"/></div>\n    </div>\n    <div class=\"intro-name-wrap\" id=\"iName\"><h1 class=\"intro-name\">Serabta</h1></div>\n    <p class=\"intro-role\" id=\"iRole\">Horumariyaha Websaydhka</p>\n    <div class=\"intro-bars\" id=\"iBars\">\n      <span></span><span></span><span></span><span></span>\n      <span></span><span></span><span></span><span></span>\n    </div>\n    <button class=\"intro-btn\" id=\"iBtn\">\u2726 Gal Websaydhka \u2726</button>\n  </div>\n  <audio id=\"iAudio\" preload=\"auto\" playsinline webkit-playsinline>\n    <source src=\"data:audio/mp3;base64,\" type=\"audio/mpeg\">\n  </audio>\n</div>\n\n<!-- \u2550\u2550\u2550 MAIN SITE \u2550\u2550\u2550 -->\n<div class=\"wrapper\">\n  <div class=\"card\" id=\"card3d\">\n    <div class=\"card-shine\" id=\"shine\"></div>\n\n    <!-- PROFIL -->\n    <div class=\"page active\" id=\"page-profil\">\n      <div class=\"photo-outer\" id=\"photoEl\">\n        <div class=\"rays\"></div>\n        <div class=\"ring3\"></div><div class=\"ring2\"></div><div class=\"ring1\"></div>\n        <div class=\"photo-inner\"><img src=\"data:image/png;base64,\" alt=\"Serabta\"/></div>\n        <div class=\"photo-shadow\"></div>\n      </div>\n      <h1 class=\"name\" id=\"nameEl\">Serabta</h1>\n      <p class=\"role\" id=\"roleEl\">Horumariyaha Websaydhka</p>\n      <div class=\"divider\" id=\"divEl\"></div>\n      <div class=\"links\">\n        <button class=\"link-btn\" id=\"btn1\" onclick=\"goTo('page-insta')\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\" ry=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><circle cx=\"17.5\" cy=\"6.5\" r=\".5\" fill=\"currentColor\" stroke=\"none\"/></svg>\n          <span>@skid_kcpn1</span>\n        </button>\n        <button class=\"link-btn\" id=\"btn2\" onclick=\"goTo('page-wa')\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z\"/></svg>\n          <span>Xiriir WhatsApp</span>\n        </button>\n      </div>\n    </div>\n\n    <!-- INSTAGRAM -->\n    <div class=\"page form-page\" id=\"page-insta\">\n      <p class=\"page-title\">Instagram</p>\n      <p class=\"subtitle\">Iska warran marka hore</p>\n      <div class=\"divider\" style=\"width:60px;opacity:1;margin-bottom:1.2rem\"></div>\n      <div class=\"field\"><label>Magacaaga *</label><input type=\"text\" id=\"nom_i\" placeholder=\"Tusaale: Axmed Cali\" oninput=\"chk('i')\"/></div>\n      <div class=\"field\"><label>Adiga waxaad tahay *</label>\n        <select id=\"profil_i\" onchange=\"chk('i')\">\n          <option value=\"\">\u2014 Dooro \u2014</option>\n          <option>Qof caadi ah</option><option>Shirkad</option>\n        </select>\n      </div>\n      <div class=\"field\"><label>Baahidaada *</label><textarea id=\"besoin_i\" placeholder=\"Tusaale: Waxaan rabaa in aan sameeyo websaydh...\" oninput=\"chk('i')\"></textarea></div>\n      <button class=\"btn-send\" id=\"btn_i\" onclick=\"sendInsta()\">\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg>\n        Fur Instagram\n      </button>\n      <button class=\"back-btn\" onclick=\"goBack('page-insta')\">\u2190 Ku noqo</button>\n    </div>\n\n    <!-- WHATSAPP -->\n    <div class=\"page form-page\" id=\"page-wa\">\n      <p class=\"page-title\">WhatsApp</p>\n      <p class=\"subtitle\">Iska warran marka hore</p>\n      <div class=\"divider\" style=\"width:60px;opacity:1;margin-bottom:1.2rem\"></div>\n      <div class=\"field\"><label>Magacaaga *</label><input type=\"text\" id=\"nom_w\" placeholder=\"Tusaale: Axmed Cali\" oninput=\"chk('w')\"/></div>\n      <div class=\"field\"><label>Adiga waxaad tahay *</label>\n        <select id=\"profil_w\" onchange=\"chk('w')\">\n          <option value=\"\">\u2014 Dooro \u2014</option>\n          <option>Qof caadi ah</option><option>Shirkad</option>\n        </select>\n      </div>\n      <div class=\"field\"><label>Baahidaada *</label><textarea id=\"besoin_w\" placeholder=\"Tusaale: Waxaan rabaa in aan sameeyo websaydh...\" oninput=\"chk('w')\"></textarea></div>\n      <button class=\"btn-send\" id=\"btn_w\" onclick=\"sendWa()\">\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z\"/></svg>\n        U dir WhatsApp\n      </button>\n      <button class=\"back-btn\" onclick=\"goBack('page-wa')\">\u2190 Ku noqo</button>\n    </div>\n\n  </div>\n</div>\n\n<script>\n// \u2550\u2550\u2550 INTRO PARTICLES\nconst ic=document.getElementById('intro-canvas'),ix=ic.getContext('2d');\nlet iw,ih,ip=[];\nfunction ir(){iw=ic.width=window.innerWidth;ih=ic.height=window.innerHeight}\nir();window.addEventListener('resize',ir);\nclass IS{constructor(){this.reset()}reset(){this.x=Math.random()*iw;this.y=Math.random()*ih;this.r=Math.random()*2+.3;this.a=Math.random()*.6+.1;this.vx=(Math.random()-.5)*.6;this.vy=(Math.random()-.5)*.6;this.c=Math.random()>.5?'201,168,76':'240,236,228';this.p=Math.random()*Math.PI*2}update(){this.x+=this.vx;this.y+=this.vy;this.p+=.04;if(this.x<0||this.x>iw||this.y<0||this.y>ih)this.reset()}draw(){const a=this.a*(.5+.5*Math.sin(this.p));ix.beginPath();ix.arc(this.x,this.y,this.r,0,Math.PI*2);ix.fillStyle=`rgba(${this.c},${a})`;ix.fill()}}\nfor(let i=0;i<250;i++)ip.push(new IS());\nlet introOn=true;\nfunction animI(){if(!introOn)return;ix.clearRect(0,0,iw,ih);// lines\nfor(let i=0;i<ip.length;i++){for(let j=i+1;j<ip.length;j++){const dx=ip[i].x-ip[j].x,dy=ip[i].y-ip[j].y,d=Math.sqrt(dx*dx+dy*dy);if(d<80){ix.beginPath();ix.moveTo(ip[i].x,ip[i].y);ix.lineTo(ip[j].x,ip[j].y);ix.strokeStyle=`rgba(201,168,76,${.05*(1-d/80)})`;ix.lineWidth=.5;ix.stroke()}}}\nip.forEach(s=>{s.update();s.draw()});requestAnimationFrame(animI)}\nanimI();\n\n// Reveal intro text\nsetTimeout(()=>{document.getElementById('iName').classList.add('show');document.getElementById('iRole').classList.add('show')},400);\nsetTimeout(()=>{document.getElementById('iBtn').classList.add('show')},1200);\n\n// Intro audio + enter\nconst iAudio=document.getElementById('iAudio');\nconst iBtn=document.getElementById('iBtn');\nconst iBars=document.getElementById('iBars');\nlet done=false;\n\nfunction finish(){if(done)return;done=true;iBars.classList.remove('show');const s=document.getElementById('intro');s.classList.add('hide');introOn=false;setTimeout(()=>s.remove(),1200)}\n\niBtn.addEventListener('click',()=>{\n  iBars.classList.add('show');\n  iBtn.style.opacity='.3';iBtn.style.pointerEvents='none';\n  iAudio.currentTime=0;iAudio.volume=1;\n  const p=iAudio.play();\n  if(p!==undefined)p.catch(()=>setTimeout(finish,1500));\n  iAudio.onended=finish;\n  iAudio.onerror=finish;\n  setTimeout(finish,15000);\n},{once:true});\n\nfunction enterSite(){\n  const s=document.getElementById('intro');\n  if(s){s.classList.add('hide');setTimeout(()=>s.remove(),1200);}\n  introOn=false;\n}\n\n// \u2550\u2550\u2550 MAIN PARTICLES\nconst cv=document.getElementById('canvas'),ctx=cv.getContext('2d');\nlet W,H,pts=[];\nfunction rsz(){W=cv.width=window.innerWidth;H=cv.height=window.innerHeight}\nrsz();window.addEventListener('resize',rsz);\nclass P{constructor(){this.reset()}reset(){this.x=Math.random()*W;this.y=Math.random()*H;this.r=Math.random()*1.8+.3;this.a=Math.random()*.5+.1;this.vx=(Math.random()-.5)*.4;this.vy=(Math.random()-.5)*.4;this.c=Math.random()>.6?'201,168,76':Math.random()>.5?'240,236,228':'139,26,26';this.p=Math.random()*Math.PI*2}update(){this.x+=this.vx;this.y+=this.vy;this.p+=.035;if(this.x<0||this.x>W||this.y<0||this.y>H)this.reset()}draw(){const a=this.a*(.5+.5*Math.sin(this.p));ctx.beginPath();ctx.arc(this.x,this.y,this.r,0,Math.PI*2);ctx.fillStyle=`rgba(${this.c},${a})`;ctx.fill()}}\nfor(let i=0;i<160;i++)pts.push(new P());\nfunction animP(){ctx.clearRect(0,0,W,H);\nfor(let i=0;i<pts.length;i++){for(let j=i+1;j<pts.length;j++){const dx=pts[i].x-pts[j].x,dy=pts[i].y-pts[j].y,d=Math.sqrt(dx*dx+dy*dy);if(d<90){ctx.beginPath();ctx.moveTo(pts[i].x,pts[i].y);ctx.lineTo(pts[j].x,pts[j].y);ctx.strokeStyle=`rgba(201,168,76,${.06*(1-d/90)})`;ctx.lineWidth=.5;ctx.stroke()}}}\npts.forEach(p=>{p.update();p.draw()});requestAnimationFrame(animP)}\nanimP();\n\n// \u2550\u2550\u2550 CARD 3D TILT\nconst card=document.getElementById('card3d'),shine=document.getElementById('shine');\ndocument.addEventListener('mousemove',e=>{\n  const r=card.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;\n  const dx=(e.clientX-cx)/(r.width/2),dy=(e.clientY-cy)/(r.height/2);\n  card.style.transform=`rotateX(${dy*-12}deg) rotateY(${dx*12}deg) scale(1.02)`;\n  card.style.transition='transform .05s';\n  shine.style.background=`radial-gradient(circle at ${50+dx*30}% ${50+dy*30}%,rgba(255,255,255,.1) 0%,transparent 60%)`;\n});\ndocument.addEventListener('mouseleave',()=>{card.style.transform='rotateX(0) rotateY(0) scale(1)';card.style.transition='transform .6s ease'});\ndocument.addEventListener('touchmove',e=>{\n  const t=e.touches[0],r=card.getBoundingClientRect();\n  const dx=(t.clientX-r.left-r.width/2)/(r.width/2),dy=(t.clientY-r.top-r.height/2)/(r.height/2);\n  card.style.transform=`rotateX(${dy*-8}deg) rotateY(${dx*8}deg)`;\n  card.style.transition='none';\n},{passive:true});\ndocument.addEventListener('touchend',()=>{card.style.transform='rotateX(0) rotateY(0)';card.style.transition='transform .6s ease'});\n\n// \u2550\u2550\u2550 ENTRANCE\nconst els=[\n  {el:document.getElementById('photoEl'),delay:400,cls:'in'},\n  {el:document.getElementById('nameEl'),delay:650,cls:'in'},\n  {el:document.getElementById('roleEl'),delay:850,cls:'in'},\n  {el:document.getElementById('divEl'),delay:1000,cls:'in'},\n  {el:document.getElementById('btn1'),delay:1150,cls:'in'},\n  {el:document.getElementById('btn2'),delay:1300,cls:'in'},\n];\nels.forEach(({el,delay,cls})=>setTimeout(()=>el&&el.classList.add(cls),delay));\n// Start float after entrance\nsetTimeout(()=>{const p=document.getElementById('photoEl');if(p)p.style.animation='photoFloat 5s ease-in-out infinite'},1500);\n\n// \u2550\u2550\u2550 NAVIGATION\nlet cur='page-profil';\nfunction goTo(id){\n  const f=document.getElementById(cur);f.classList.add('exit');\n  setTimeout(()=>f.classList.remove('active','exit'),500);\n  setTimeout(()=>{document.getElementById(id).classList.add('active');cur=id},220);\n}\nfunction goBack(id){\n  const f=document.getElementById(id);f.classList.add('exit');\n  setTimeout(()=>{f.classList.remove('active','exit');document.getElementById('page-profil').classList.add('active');cur='page-profil'},450);\n}\n\n// \u2550\u2550\u2550 FORM\nfunction chk(s){\n  const ok=document.getElementById('nom_'+s).value.trim()!==''&&document.getElementById('profil_'+s).value!==''&&document.getElementById('besoin_'+s).value.trim()!=='';\n  document.getElementById('btn_'+s).classList.toggle('active',ok);\n}\nfunction sendInsta(){window.open('https://www.instagram.com/skid_kcpn1/','_blank')}\nfunction sendWa(){\n  const n=document.getElementById('nom_w').value.trim(),p=document.getElementById('profil_w').value,b=document.getElementById('besoin_w').value.trim();\n  window.open('https://wa.me/252629464789?text='+encodeURIComponent(`Salaan Serabta \ud83d\udc4b\\n\\nMagacaygu waa: ${n}\\nAniga waxaan ahay: ${p}\\nBaahidayda: ${b}`),'_blank');\n}\n\n// \u2550\u2550\u2550 RIPPLE\ndocument.querySelectorAll('.link-btn,.btn-send,.intro-btn').forEach(b=>{\n  b.addEventListener('click',e=>{\n    const r=document.createElement('span'),rc=b.getBoundingClientRect();\n    r.style.cssText=`position:absolute;width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.5);left:${e.clientX-rc.left-3}px;top:${e.clientY-rc.top-3}px;transform:scale(0);animation:ripple .6s ease forwards;pointer-events:none;z-index:10`;\n    b.appendChild(r);setTimeout(()=>r.remove(),700);\n  });\n});\nconst st=document.createElement('style');st.textContent='@keyframes ripple{to{transform:scale(40);opacity:0}}';document.head.appendChild(st);\n</script>\n</body>\n</html>"

async function handleRequest(request) {
  return new Response(HTML, {
    headers: { 'Content-Type': 'text/html;charset=UTF-8' }
  })
}
